package android.app;import android.content.*;import android.os.*;public abstract class Service extends Context {public static final int START_NOT_STICKY=2;public static boolean rejectForeground;public boolean foreground,stopped;public int serviceType;public Notification last;public abstract IBinder onBind(Intent i);public int onStartCommand(Intent i,int flags,int id){return 0;}public void startForeground(int id,Notification n){if(rejectForeground)throw new SecurityException("sensitive FGS error");foreground=true;last=n;}public void startForeground(int id,Notification n,int type){serviceType=type;startForeground(id,n);}public void stopForeground(boolean remove){foreground=false;}public boolean stopSelfResult(int id){stopped=true;return true;}public void stopSelf(){stopped=true;}public void onTimeout(int startId,int type){}public void onDestroy(){} }